<?php
namespace Dth\Crm\Filament\Resources\CompanyResource\RelationManagers; use Filament\Resources\RelationManagers\RelationManager; use Filament\Schemas\Schema; use Filament\Tables\Table; use Filament\Tables\Columns\TextColumn; use Filament\Actions; use Filament\Forms\Components\{Select,Textarea}; use Dth\Crm\Models\Staff;
class AssignmentsRelationManager extends RelationManager {protected static string $relationship='assignments';public static function getTitle($o,string $p):string{return 'Phân công doanh nghiệp';} public function form(Schema $s):Schema{return $s->components([Select::make('staff_id')->label('Nhân viên')->options(fn()=>Staff::where('employment_status','active')->pluck('name','id')->all())->required()->searchable(),Select::make('assignment_type')->options(['owner'=>'Chủ sở hữu','support'=>'Hỗ trợ'])->default('owner'),Select::make('status')->options(['active'=>'Hoạt động','ended'=>'Kết thúc','cancelled'=>'Hủy'])->default('active'),Textarea::make('reason')->label('Lý do')]);} public function table(Table $t):Table{return $t->columns([TextColumn::make('staff.name')->label('Nhân viên'),TextColumn::make('assignment_type')->badge(),TextColumn::make('status')->badge(),TextColumn::make('starts_at')->dateTime('d/m/Y H:i')])->headerActions([Actions\CreateAction::make()->mutateDataUsing(fn($d)=>$d+['assigned_by_user_id'=>auth()->id(),'starts_at'=>now()])])->recordActions([Actions\EditAction::make(),Actions\DeleteAction::make()]);}}
